start_time=$(date +%s)
convert="hg2cu"
pnum=32
while [[ -n $1 ]]
do
    case "$1" in
        --root_dir)          root_dir=$2
            shift;;
        --convert)           convert=$2
            shift;;
        --pnum)              pnum=$2
            shift;;
        *) echo "Usage  : ./build_hggc.sh [options]"
           echo "Options:"
           echo "============="
           echo "       --root_dir <dir>       :     reset root dir of find and replace, default is current cutlass dir"
           echo "       --convert <str>        :     specified convert action, can be hg2cu/cu2hg. default is hg2cu"
           echo "       --pnum  <int>          :     specified the number of process. default is 32"
           exit 1;;
    esac
    shift
done

echo "================ start $convert for cutlass ================"
#echo "convert action is: ${convert}"
dir=$(dirname "$(dirname "${PWD}/${0}")")
if [[ -n ${root_dir} ]]; then
    dir=${root_dir}
fi

echo "base dir is: ${dir}"
filename=$(basename "$0")

# Replace the hggc/cuda string function.
FindAndReplace() {
    replacefile=$1
    #echo "replace file: $replacefile"

    elements=(${list} ${nvrtc_list} ${header_list})
    # if you want to get better performance, you can try to increase inner_loop.
    inner_loop=32
    for (( i=0; i<${#elements[@]}; i+=inner_loop ))
    do
        grep_str=""
        sed_list=()
        for (( j=i; j<${#elements[@]} && j<i+inner_loop; j+=1 ))
        do
            str=${elements[$j]}
            arr=(${str//:/ })
            cuda=${arr[0]}
            hggc=${arr[1]}
            oldstr=${hggc}
            newstr=${cuda}
            if [[ "cu2hg" == "${convert}" ]]; then
                oldstr=${cuda}
                newstr=${hggc}
            fi
            grep_str="${grep_str}|${oldstr}"
            sed_list+=("-e 's/${oldstr}/${newstr}/g'")

        done
        grep_str="${grep_str#?}"
        if [[ -n `grep -E -lIw "${grep_str}" $replacefile` ]]; then
            cmd="sed -i ${sed_list[@]} $replacefile"
            eval "$cmd"
        fi
    done
}

#list all files
all_files=`find ${dir}/ ! -path "${dir}/build*" ! -path "${dir}/test/*" ! -path "${dir}/docs/*" ! -path "${dir}/examples/*" \
! -path "${dir}/ppu/*" ! -path "${dir}/cmake/*" ! -path "${dir}/\.*" -regextype egrep -regex ".*\.(h|hpp|c|cpp|cu)" -type f`

#let the function and variable can be seen by all sub process.
typeset -xf FindAndReplace
typeset -x list nvrtc_list header_list
typeset -x convert

#Run FindAndReplace function by muti-process, one file only dealed by one process
echo "${all_files}" | xargs -I {} -P ${pnum} bash -c 'FindAndReplace {}'

end_time=$(date +%s)
echo "================ finished $convert for cutlass ================"
echo "        eplased time: $(($end_time - $start_time)) seconds"
